import dlanhs = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs( 'row-major', 'max', 2, A, 2, work ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs( 5, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( true, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( false, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( null, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( void 0, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( [], 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( {}, 'max', 2, A, 2, work ); // $ExpectError
	dlanhs( ( x: number ): number => x, 'max', 2, A, 2, work ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs( 'row-major', 5, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', true, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', false, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', null, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', void 0, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', [], 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', {}, 2, A, 2, work ); // $ExpectError
	dlanhs( 'row-major', ( x: number ): number => x, 2, A, 2, work ); // $ExpectError
}

