// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs(); // $ExpectError
	dlanhs( 'row-major' ); // $ExpectError
	dlanhs( 'row-major', 'max' ); // $ExpectError
	dlanhs( 'row-major', 'max', 2 ); // $ExpectError
	dlanhs( 'row-major', 'max', 2, A ); // $ExpectError
	dlanhs( 'row-major', 'max', 2, A, 2 ); // $ExpectError
	dlanhs( 'row-major', 'max', 2, A, 2, work, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs.ndarray( 'max', 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs.ndarray( 5, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( true, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( false, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( null, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( void 0, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( [], 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( {}, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
	dlanhs.ndarray( ( x: number ): number => x, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
}

