// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	const work = new Float64Array( 2 );

	dlanhs.ndarray(); // $ExpectError
	dlanhs.ndarray( 'max' ); // $ExpectError
	dlanhs.ndarray( 'max', 2 ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2 ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2, 1 ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2, 1, 0 ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2, 1, 0, work ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2, 1, 0, work, 1 ); // $ExpectError
	dlanhs.ndarray( 'max', 2, A, 2, 1, 0, work, 1, 0, 10 ); // $ExpectError
}
